// 定义结构体
struct Rectangle {
    width: u32,
    height: u32,
}

// impl块定义方法
impl Rectangle {
    // 关联函数 (不需要self)
    fn new(width: u32, height: u32) -> Self {
        Self { width, height }
    }

    // 方法 (需要&self)
    fn area(&self) -> u32 {
        self.width * self.height
    }

    // 可变方法
    fn resize(&mut self, w: u32, h: u32) {
        self.width = w;
        self.height = h;
    }
}

fn main() {
    // 创建实例
    let rect = Rectangle::new(30, 50);

    // 调用方法 (自动解引用)
    println!("面积: {}", rect.area());
}

